        tombstone = entry.get('tombstone')
        if tombstone:
            raise AnsibleError('{0} (module_utils {1} in collection {2}; removal version: {3}; removal date: {4})'.format(
                tombstone.get('warning_text', tombstone.get('message', 'This module was removed')),
                '.'.join(candidate), collection, tombstone.get('removal_version'), tombstone.get('removal_date')))
        redirect = entry.get('redirect')
        if not redirect:
            return False
        deprecation = entry.get('deprecation')
        if deprecation:
            display.deprecated(deprecation.get('warning_text', 'Module utility {0} is deprecated'.format('.'.join(candidate))),
                               version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                               collection_name=collection)
        if redirect.startswith('ansible_collections.') or redirect.startswith('ansible.module_utils.'):
            target = redirect
        else:
            parts = redirect.split('.')
            if len(parts) < 3:
                raise AnsibleError('Invalid module_utils redirect {0}'.format(redirect))
            target = 'ansible_collections.{0}.{1}.plugins.module_utils.{2}'.format(parts[0], parts[1], '.'.join(parts[2:]))
        self.redirected = True
        self.is_package = False
        self.source_code = "import sys\nimport {0} as mod\nsys.modules[{1!r}] = mod\n".format(target, '.'.join(candidate))
        self.path = self.output_path = '/'.join(candidate) + '.py'
        self.dependencies = (tuple(target.split('.')),)
        return True

    def _routing_collection(self, candidate):
        raise NotImplementedError

    def _local(self, candidate):
        raise NotImplementedError


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)

    def _routing_collection(self, candidate):
        return 'ansible.builtin'

    def _local(self, candidate):
        relative = candidate[2:]
        if not relative:
            return False
        try:
            info = ModuleInfo(relative[-1], [os.path.join(p, *relative[:-1]) for p in self.mu_paths])
        except (ImportError, AttributeError, TypeError):
            return False
        if not info.py_src and not info.pkg_dir:
            raise AnsibleError('Could not find python source for imported module support code for {0}'.format('.'.join(candidate)))
        self.is_package = info.pkg_dir
        self.source_code = info.get_source()
        self.path = info.path
        return True


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 5
    redirect_first = True

    def _routing_collection(self, candidate):
        return '.'.join(candidate[1:3])

    def _local(self, candidate):
        if len(candidate) <= self.prefix_length:
            return False
        collection = self._routing_collection(candidate)
        try:
            pkg = import_module('ansible_collections.' + collection)
        except ImportError:
            raise AnsibleError('unable to locate collection {0}'.format(collection))
        relative = candidate[3:]
        for root in pkg.__path__:
            base = os.path.join(root, *relative)
            for path, is_package in ((os.path.join(base, '__init__.py'), True), (base + '.py', False)):
                if os.path.isfile(path):
                    self.source_code = _slurp(path)
                    self.path = path
                    self.is_package = is_package
                    return True
        return False


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    """Bundle the transitive module_utils closure using a work queue."""
    module_utils_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    module_utils_paths.append(_MODULE_UTILS_PATH)
    pending = deque([(name, module_fqn, data, False)])
    queued = set()
    written = set(zf.namelist())

    def add_file(parts, source, path, is_package=False):
        key = parts + (('__init__',) if is_package else ())
        if key in py_module_names or key in queued:
            return
        queued.add(key)
        py_module_cache[key] = (source, path)
        filename = '/'.join(parts) + ('/__init__.py' if is_package else '.py')
        if filename not in written:
            zf.writestr(filename, source)
            written.add(filename)
        display.vvvvv('Using module_utils file %s' % to_text(path, errors='surrogate_or_strict'))
        pending.append((parts[-1], '.'.join(parts), source, is_package))

    def add_parents(parts):
        # The two base package files are always in the payload, even if the
        # caller has not populated them yet.
        for prefix, source in ((('ansible',), b'from pkgutil import extend_path\n__path__=extend_path(__path__,__name__)\n'),
                               (('ansible', 'module_utils'), b'from pkgutil import extend_path\n__path__=extend_path(__path__,__name__)\n')):
            filename = '/'.join(prefix) + '/__init__.py'
            if filename not in written:
                zf.writestr(filename, source)
                written.add(filename)
        start = 1 if parts[0] == 'ansible_collections' else 3
        for length in range(start, len(parts)):
            parent = parts[:length]
            filename = '/'.join(parent) + '/__init__.py'
            if filename in written:
                continue
            if length > 5 and parts[0] == 'ansible_collections':
                locator = CollectionModuleUtilLocator(parent)
                if locator.found and locator.is_package:
                    add_file(parent, locator.source_code, locator.path, True)
                    continue
            if length > 2 and parts[0] == 'ansible':
                locator = LegacyModuleUtilLocator(parent, mu_paths=module_utils_paths)
                if locator.found and locator.is_package:
                    add_file(parent, locator.source_code, locator.path, True)
                    continue
            add_file(parent, b'', filename, True)

    add_parents(('ansible', 'module_utils', 'basic'))
    add_file(('ansible', 'module_utils', 'basic'), ModuleInfo('basic', module_utils_paths).get_source(),
             os.path.join(_MODULE_UTILS_PATH, 'basic.py'))
    while pending:
        current_name, current_fqn, source, is_package = pending.popleft()
        key = tuple(current_fqn.split('.')) + (('__init__',) if is_package else ())
        if key in py_module_names:
            continue
        try:
            tree = compile(source, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as exc:
            raise AnsibleError('Unable to import %s due to %s' % (current_name, exc.msg))
        finder = ModuleDepFinder(current_fqn, is_package=is_package)
        finder.visit(tree)
        py_module_names.add(key)
        for dependency in sorted(finder.submodules):
            if dependency[:3] == ('ansible', 'module_utils', 'six'):
                dependency = dependency[:3]
            if dependency[:2] == ('ansible', 'module_utils'):
                locator = LegacyModuleUtilLocator(dependency, is_ambiguous=True, mu_paths=module_utils_paths)
            elif dependency[:5] == ('ansible_collections',) + dependency[1:3] + ('plugins', 'module_utils') and len(dependency) > 5:
                locator = CollectionModuleUtilLocator(dependency, is_ambiguous=True)
            else:
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for {0}. Looked for ({1})'.format(
                    current_fqn, ', '.join(locator.candidate_names_joined())))
            parts = locator.name_parts
            add_parents(parts)
            add_file(parts, locator.source_code, locator.path, locator.is_package)
            for target in locator.dependencies:
                if target[:2] == ('ansible', 'module_utils'):
                    target_locator = LegacyModuleUtilLocator(target, mu_paths=module_utils_paths)
                else:
                    target_locator = CollectionModuleUtilLocator(target)
                if not target_locator.found:
                    raise AnsibleError('Could not find imported module support code for {0}. Looked for ({1})'.format(
                        current_fqn, ', '.join(target_locator.candidate_names_joined())))
                add_parents(target_locator.name_parts)
                add_file(target_locator.name_parts, target_locator.source_code, target_locator.path, target_locator.is_package)
        py_module_cache.pop(key, None)

def _is_binary(b_module_data):
    textchars = bytearray(set([7, 8, 9, 10, 12, 13, 27]) | set(range(0x20, 0x100)) - set([0x7f]))
    start = b_module_data[:1024]
    return bool(start.translate(None, textchars))


